from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request

DEFAULT_BASE_URL = \"https://api.openai.com/v1\"
DEFAULT_MODEL = \"gpt-4.1-mini\"
DEFAULT_TIMEOUT = 120.0


class OpenAIError(Exception):
    \"\"\"Raised when the API returns an error or the request fails.\"\"\"

    def __init__(self, message: str, status: int | None = None, body: str | None = None):
        super().__init__(message)
        self.status = status
        self.body = body


class OpenAIClient:
    \"\"\"Blocking client for the OpenAI Responses API (stdlib only).\"\"\"

    def __init__(
        self,
        api_key: str | None = None,
        base_url: str = DEFAULT_BASE_URL,
        model: str = DEFAULT_MODEL,
        timeout: float = DEFAULT_TIMEOUT,
    ):
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise OpenAIError(
                \"No API key: pass api_key= or set the OPENAI_API_KEY environment variable\"
            )
        self.base_url = base_url.rstrip(\"/\")
        self.model = model
        self.timeout = timeout

    def create_response(
        self,
        input_text: str,
        model: str | None = None,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        store: bool = False,
        **extra,
    ) -> dict:
        \"\"\"Create a response and return the raw decoded JSON.\"\"\"
        payload: dict = {
            \"model\": model or self.model,
            \"input\": input_text,
            \"store\": store,
        }
        if instructions is not None:
            payload[\"instructions\"] = instructions
        if max_output_tokens is not None:
            payload[\"max_output_tokens\"] = max_output_tokens
        payload.update(extra)
        return self._post(\"/responses\", payload)

    def ask(self, prompt: str, **kwargs) -> str:
        \"\"\"Send a single text prompt and return the assistant's text.\"\"\"
        return extract_text(self.create_response(prompt, **kwargs))

    def _post(self, path: str, payload: dict) -> dict:
        request = urllib.request.Request(
            url=self.base_url + path,
            data=json.dumps(payload).encode(\"utf-8\"),
            headers={
                \"Authorization\": f\"Bearer {self.api_key}\",
                \"Content-Type\": \"application/json\",
            },
            method=\"POST\",
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                return json.loads(response.read().decode(\"utf-8\"))
        except urllib.error.HTTPError as exc:
            body = exc.read().decode(\"utf-8\", errors=\"replace\")
            detail = body
            try:
                detail = json.loads(body).get(\"error\", {}).get(\"message\", body)
            except ValueError:
                pass
            raise OpenAIError(
                f\"API error {exc.code}: {detail}\", status=exc.code, body=body
            ) from exc
        except urllib.error.URLError as exc:
            raise OpenAIError(f\"Request failed: {exc.reason}\") from exc


def extract_text(response: dict) -> str:
    \"\"\"Pull the assistant's text out of a Responses API result.\"\"\"
    if isinstance(response.get(\"output_text\"), str):
        return response[\"output_text\"]
    parts = []
    for item in response.get(\"output\", []):
        if item.get(\"type\") "'!= "message":
            continue
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                parts.append(content.get("text", ""))
    return "".join(parts)


def main(argv: list[str]) -> int:
    if not argv:
        print("usage: python3 openai_client.py <prompt>", file=sys.stderr)
        return 2
    try:
        print(OpenAIClient().ask(" ".join(argv)))
    except OpenAIError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
